#include "../ring3_common.hpp"
static constexpr u32 W=620,H=460; static u32*pix; static u64 events,win; static bool dirty=true; static char path[96]="/Home/"; static char listing[1024];
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static void refresh(){for(u32 i=0;i<sizeof(listing);i++)listing[i]=0;sc(36,(u64)path,(u64)listing,sizeof(listing)-1);dirty=true;}
static void setpath(const char*s){u32 i=0;for(;s[i]&&i<94;i++)path[i]=s[i];path[i]=0;refresh();}
static void draw(){fill(pix,W*H,0x00f5f7fa);rect(pix,W,H,0,0,W,54,0x001d3557);text(pix,W,H,20,19,"DAVIS FILES",0x00ffffff,2);rr(18,70,W-36,42,14,0x00ffffff);text(pix,W,H,34,85,path,0x00253445,1);const char* names[]={"DOCUMENTS","DOWNLOADS","PICTURES","MUSIC","VIDEOS","SYSTEM"};for(int i=0;i<6;i++){int y=130+i*45;rr(20,y,178,34,10,0x00e9eef5);text(pix,W,H,34,y+12,names[i],0x002a4c70,1);}rr(216,130,W-236,286,14,0x00ffffff);text(pix,W,H,236,150,"AVAILABLE ITEMS",0x002a4c70,1);int y=180;char line[80];u32 li=0;for(u32 i=0;listing[i]&&y<398;i++){if(listing[i]=='\n'){line[li]=0;text(pix,W,H,238,y,line,0x003b4652,1);y+=24;li=0;}else if(li<78)line[li++]=listing[i];}text(pix,W,H,20,H-22,"CLICK A FOLDER TO OPEN ITS LIVE DAVIS FILE NAMESPACE",0x00616d79,1);sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,180,90);if(!win)sc(0,2);refresh();for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*p=(PtrEv*)m.payload;if((p->flags&1)&&p->x>=20&&p->x<198&&p->y>=130&&p->y<400){int i=(p->y-130)/45;const char* ps[]={"/Home/Documents/","/Home/Downloads/","/Home/Pictures/","/Home/Music/","/Home/Videos/","/System/"};if(i>=0&&i<6)setpath(ps[i]);}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
